"""Copies web/index.html into firmware/led_controller/page.h.

The ESP32 serves the control page from its own memory, so the HTML has to be
compiled in as a C string. Run this after editing web/index.html:

    python3 tools/embed_page.py
"""
from pathlib import Path

ROOT = Path(__file__).resolve().parent.parent
html = (ROOT / "web" / "index.html").read_text(encoding="utf-8")

DELIM = "rawpage"
if f"){DELIM}\"" in html:
    raise SystemExit(f"index.html contains ){DELIM}\" which would end the string early")

header = (
    "// Generated by tools/embed_page.py from web/index.html. Don't edit by hand.\n"
    "#pragma once\n"
    "#include <pgmspace.h>\n\n"
    f"const char CONTROL_PAGE[] PROGMEM = R\"{DELIM}(\n{html}){DELIM}\";\n"
)
out = ROOT / "firmware" / "led_controller" / "page.h"
out.write_text(header, encoding="utf-8")
print(f"Wrote {out.relative_to(ROOT)} ({len(html):,} bytes of HTML)")
